# -*- coding: utf-8 -*-
from ru_base import *

# ---- Предлоги
PCASE = {'родительный падеж': ['у', 'без', 'для', 'до', 'от', 'из', 'около', 'возле', 'кроме'], 'дательный падеж': ['к', 'благодаря', 'согласно', 'вопреки'], 'винительный падеж': ['через', 'про', 'сквозь'],
         'творительный падеж': ['между', 'перед', 'над'], 'предложный падеж': ['при', 'о', 'об']}
cls(BM, 'r_predlog', 'Предлоги и падежи — Predloglar', [6, 7, 8], PCASE, lambda x: f'С каким падежом употребляется предлог «{x}»?', lambda c: f'Какой предлог употребляется с падежом: {c}?', lambda c: f'Какой предлог НЕ употребляется с падежом: {c}?', 'предлоги ko‘makchi', decoys=['именительный падеж'])
PR = [('Я иду ___ школу.', 'в', ['из', 'от', 'у']), ('Мы живём ___ городе.', 'в', ['на', 'из', 'к']), ('Он работает ___ заводе.', 'на', ['из', 'к', 'у']), ('Книга лежит ___ столе.', 'на', ['к', 'из', 'у']),
      ('Мы приехали ___ Ташкента.', 'из', ['в', 'на', 'к']), ('Он вернулся ___ работы.', 'с', ['в', 'на', 'к']), ('Я иду ___ другу.', 'к', ['в', 'на', 'из']), ('Мальчик стоит ___ дома.', 'у', ['в', 'к', 'из']),
      ('Я купил подарок ___ мамы.', 'для', ['к', 'в', 'из']), ('Лампа висит ___ столом.', 'над', ['в', 'к', 'из']), ('Мы пришли ___ почту.', 'на', ['из', 'у', 'от']), ('Он вернулся ___ почты.', 'с', ['в', 'на', 'к']),
      ('Книга лежит ___ сумке.', 'в', ['на', 'к', 'из']), ('Мы поехали ___ бабушке.', 'к', ['в', 'на', 'из']), ('Я пришёл ___ школы.', 'из', ['в', 'на', 'к'])]
def pr():
    q, r, w = ch(PR); return mc(f'Выберите предлог: {q}', r, w)
B.topic(BM, 'r_predlog2', 'Выберите предлог', [6, 7, 8], pr, pr, pr, 'предлог в на из с')

# ---- Союзы
cls(BM, 'r_soyuz', 'Союзы — Bogʻlovchilar', [7, 8], {'соединительный союз': ['и', 'да (= и)', 'также', 'тоже'], 'противительный союз': ['но', 'а', 'однако', 'зато'], 'разделительный союз': ['или', 'либо', 'то... то'],
    'подчинительный союз': ['потому что', 'если', 'чтобы', 'хотя', 'когда', 'так как', 'что']},
    lambda x: f'Какой это союз: «{x}»?', lambda c: f'Какой из этих союзов — {c}?', lambda c: f'Какое слово НЕ входит в группу «{c}»?', 'союзы bogʻlovchi', decoys=['сочинительный (без значения)'])
SZ = []
for q in ['Я пришёл, ___ помочь.', 'Он учится, ___ стать врачом.', 'Я хочу, ___ ты пришёл.', 'Мама просит, ___ мы пришли рано.', 'Мы открыли окно, ___ проветрить комнату.']: SZ.append((q, 'чтобы', ['что бы', 'чтобь', 'штобы']))
for q in ['Дорога дальняя, ___ красивая.', 'Зимой холодно, ___ можно кататься на лыжах.', 'Задача трудная, ___ интересная.', 'Урок длинный, ___ полезный.']: SZ.append((q, 'зато', ['за то', 'зота', 'за-то']))
for q in ['Я люблю футбол. Брат ___ любит футбол.', 'Ты идёшь? Я ___ иду.', 'Он ___ ученик нашей школы.', 'Ты устал, и я ___ устал.']: SZ.append((q, 'тоже', ['то же', 'то-же', 'тожэ']))
for q in ['Я не пошёл гулять, ___ шёл дождь.', 'Он опоздал, ___ проспал.', 'Мы остались дома, ___ было холодно.', 'Она плачет, ___ ей грустно.']: SZ.append((q, 'потому что', ['по тому что', 'потомучто', 'потому-что']))
def sz():
    q, r, w = ch(SZ); return mc(f'Выберите правильное написание: {q}', r, w)
def sz3():
    return ch([mc('Как правильно писать: цель действия (Я пришёл, ___ помочь)?', 'чтобы', ['что бы', 'чтобь', 'штобы']), mc('Как правильно: противопоставление (Дорога дальняя, ___ красивая)?', 'зато', ['за то', 'зота', 'зотто']),
               mc('Как правильно: причина (Я не пошёл, ___ болел)?', 'потому что', ['по тому что', 'потомучто', 'потому-что']), mc('Как правильно: «тоже» = «и»? (Я ___ пойду.)', 'тоже', ['то же', 'тожэ', 'то-же']),
               mc('Какой из союзов пишется слитно?', 'чтобы', ['потому что', 'так как', 'для того чтобы'])])
B.topic(BM, 'r_soyuz2', 'Правописание союзов', [7, 8], sz, sz, lambda: ch([sz, sz3])(), 'чтобы зато тоже потому что')

